void main() {
  vec2 px = 1.0 / iChannelResolution[0].xy;
  vec3 sum = vec3(0.0);
  for (int x = 0; x < 4; x++) {
    for (int y = 0; y < 4; y++) {
      sum += texture2D(iChannel0, uv + vec2(float(x) * 2.0 - 3.0, float(y) * 2.0 - 3.0) * px).rgb;
    }
  }
  gl_FragColor = vec4(sum / 16.0, 1.0);
}

void main() {
  vec2 px = spread / iChannelResolution[0].xy;
  vec3 sum = vec3(0.0);
  float total = 0.0;
  for (int x = -2; x <= 2; x++) {
    for (int y = -2; y <= 2; y++) {
      float w = exp(-float(x * x + y * y) / 4.0);
      sum += w * texture2D(iChannel0, uv + vec2(float(x), float(y)) * px).rgb;
      total += w;
    }
  }
  gl_FragColor = vec4(sum / total, 1.0);
}

void main() {
  vec2 g = uv * vec2(5.0, 8.0);
  float row = floor(g.y);
  g.x += 0.5 * mod(row, 2.0) + 0.3 * ghee_hash(vec2(row, 7.0));
  vec2 cell = floor(g);
  float h = ghee_hash(cell);
  float k = ghee_hash(cell + 17.0);
  vec2 f = fract(g) - 0.5 - (vec2(h, k) - 0.5) * 0.06;
  vec2 size = vec2(0.43, 0.39) - vec2(0.06 * k, 0.05 * h);
  float r = 0.12 + 0.1 * h;
  vec2 q = abs(f) - size + r;
  float d = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
  d += 0.015 * sin(f.x * 37.0 + h * 20.0) * sin(f.y * 29.0 + k * 20.0);
  float stone = 1.0 - smoothstep(-0.03, 0.01, d);
  vec2 n = (f / size * 0.8 + (vec2(h, k) - 0.5) * 0.5) * stone;
  gl_FragColor = vec4(n * 0.5 + 0.5, stone, fract(h * 7.0 + k));
}

void main() {
  float aspect = iResolution.x / iResolution.y;
  vec2 q = vec2(uv.x, 1.0 - uv.y);
  vec2 p = vec2(q.x * aspect + q.y * slant, q.y);
  float lane = floor(p.x * 110.0);
  float h = ghee_hash(lane);
  float y = fract(p.y * (0.8 + h) - iTime * (1.6 + h) - h * 13.0);
  float drop = smoothstep(0.0, 0.03, y) * (1.0 - smoothstep(0.03, 0.16, y));
  drop *= 1.0 - smoothstep(0.1, 0.35, abs(fract(p.x * 110.0) - 0.5));
  drop *= step(0.55, ghee_hash(lane + floor(iTime * 0.7 + h * 5.0) * 17.0));

  vec2 cell = floor(vec2(q.x * aspect * 24.0, q.y * 40.0));
  float k = ghee_hash(cell.x * 13.0 + cell.y * 7.0);
  float age = fract(iTime * 1.5 + k * 9.0);
  vec2 at = fract(vec2(q.x * aspect * 24.0, q.y * 40.0)) - vec2(0.2 + 0.6 * k, 0.5);
  float splash = exp(-dot(at, at * vec2(1.0, 0.25)) * 60.0 / (0.2 + age)) * (1.0 - age) * step(base, q.y);

  vec3 col = texture2D(iChannel0, uv).rgb;
  vec3 light = vec3(0.0);
  if (gl_FragCoord.x >= 0.0) light = texture2D(iChannel1, vec2(uv.x, 1.0 - min(q.y, 2.0 * base - q.y))).rgb;
  gl_FragColor = vec4(col + (drop + splash) * amount * (vec3(0.05) + light * 2.0), 1.0);
}
